<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); $authorityId=$scope['authority_id']; ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Authority-Administration – MeldeVerkehr</title>
<style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:1050px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}input,select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #bac5d1;border-radius:8px}button{padding:9px 13px;border:0;border-radius:9px;background:#172033;color:white;font-weight:700}.danger{background:#8e1f1f}.message,.error,.token{padding:11px;border-radius:8px;margin:8px 0}.message{border:1px solid #8fb799}.error{border:1px solid #c99}.token{border:1px solid #d6b36b;background:#fffaf0;font-family:ui-monospace,monospace;word-break:break-all}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #e5e9ee;text-align:left}.muted{color:#66758a}</style></head><body><main>
<p><a href="/authority?authority=<?= rawurlencode($authorityId) ?>">← Behördenportal</a></p><h1>Authority-Administration – <?= $e($scope['authority_name']) ?></h1>
<?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?><?php if($rawToken):?><div class="token"><strong>API-Token – nur jetzt sichtbar:</strong><br><?= $e($rawToken) ?></div><?php endif;?>
<section class="card"><h2>Benutzerzugriff zuordnen</h2><form method="post" action="/authority/<?= rawurlencode($authorityId) ?>/users"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><div class="grid"><input type="email" name="email" placeholder="E-Mail eines bestehenden aktiven Nutzers" required><select name="scope_role"><option value="AUTHORITY_USER">AUTHORITY_USER</option><option value="AUTHORITY_ADMIN">AUTHORITY_ADMIN</option></select></div><button type="submit">Zugriff zuordnen</button></form><h3>Aktuelle Benutzer</h3><table><tr><th>Name</th><th>E-Mail</th><th>Scope</th><th>Status</th></tr><?php foreach($users as $u):?><tr><td><?= $e($u['first_name'].' '.$u['last_name']) ?></td><td><?= $e($u['email']) ?></td><td><?= $e($u['scope_role']) ?></td><td><?= $e($u['status']) ?></td></tr><?php endforeach;?></table></section>
<section class="card"><h2>API-Token erstellen</h2><p class="muted">Der Klartext-Token wird nur einmal angezeigt. Gespeichert wird ausschließlich SHA-256.</p><form method="post" action="/authority/<?= rawurlencode($authorityId) ?>/tokens"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><div class="grid"><input name="name" placeholder="Tokenname" required><input type="date" name="expires_at"></div><p><label><input type="checkbox" name="scopes[]" value="cases:read"> cases:read</label> <label><input type="checkbox" name="scopes[]" value="inquiries:write"> inquiries:write</label> <label><input type="checkbox" name="scopes[]" value="exports:read"> exports:read</label> <label><input type="checkbox" name="scopes[]" value="holder:read"> holder:read</label> <label><input type="checkbox" name="scopes[]" value="holder:write"> holder:write</label></p><button type="submit">Token erstellen</button></form><h3>Tokens</h3><table><tr><th>Name</th><th>Prefix</th><th>Scopes</th><th>Ablauf</th><th>Aktion</th></tr><?php foreach($tokens as $t):?><tr><td><?= $e($t['name']) ?></td><td><?= $e($t['token_prefix']) ?></td><td><?= $e(implode(', ',$t['scopes'])) ?></td><td><?= $e($t['expires_at']??'–') ?></td><td><?php if($t['status']==='ACTIVE'):?><form method="post" action="/authority/tokens/<?= rawurlencode($t['id']) ?>/revoke"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="authority_id" value="<?= $e($authorityId) ?>"><button class="danger" type="submit">Widerrufen</button></form><?php else:?><?= $e($t['status']) ?><?php endif;?></td></tr><?php endforeach;?></table></section>
</main></body></html>